'QZ_Not_Running' => 'A QZ Tray nem fut ezen a számítógépen. Telepítse a qz.io oldalról, tartsa futva, majd engedélyezze ezt a webhelyet, amikor a QZ rákérdez.',
'Detect_Printers' => 'Nyomtatók felismerése',
'QZ_Download_Cert' => 'Tanúsítvány letöltése (override.crt)',
'QZ_Setup_Title' => 'A QZ Tray nyomtatás beállítása (egyszer, minden címkét nyomtató számítógépen)',
'QZ_Step_Install' => '1. Telepítse a QZ Trayt erre a számítógépre — töltse le ingyen a qz.io oldalról, majd indítsa el, és hagyja futni (Windows alatt a tálcán, macOS alatt a menüsorban található).',
'QZ_Step_Connect' => '2. Csatlakoztassa a címkenyomtatót USB-n, és ellenőrizze, hogy telepítve van-e az operációs rendszerben (Windows: Beállítások > Nyomtatók és szkennerek — macOS: Rendszerbeállítások > Nyomtatók és szkennerek).',
'QZ_Step_Detect' => '3. Kattintson a fenti „Nyomtató neve” melletti ⟳ gombra a számítógép nyomtatóinak felismeréséhez, majd válassza ki a címkenyomtatót. Hagyja üresen a mezőt a számítógép alapértelmezett nyomtatójának használatához.',
'QZ_Step_Cert' => '4. Az engedélykérő ablak nélküli nyomtatáshoz töltse le az alábbi tanúsítványt, és másolja a QZ Tray telepítési mappájába override.crt névre átnevezve (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Ezután lépjen ki a QZ Trayből, és indítsa újra.',
'QZ_Step_Test' => '5. Kattintson alább a „Tesztcímke nyomtatása” gombra. Ha a QZ Tray engedélyt kér, kattintson az Engedélyezés gombra — telepített tanúsítvánnyal többé nem fog kérdezni.',
'QZ_Step_Save' => '6. Kattintson a Küldés gombra a beállítások mentéséhez. A Vonalkód nyomtatása oldal címkéi mostantól közvetlenül erre a nyomtatóra kerülnek, böngészős nyomtatási párbeszédablak nélkül.',
'QZ_Setup_Note' => 'A QZ Tray azon a számítógépen fut, amelyről böngészik, így akkor is működik, ha a Stocky távoli szerveren fut. Minden címkét nyomtató számítógépre telepíteni kell a QZ Trayt.',

