'Label_Render_Mode' => 'Címke megjelenítése',
'Label_Render_Mode_Hint' => 'A címke rajzolásának módja. A nyomtatóbetűk a leggyorsabbak és a legélesebb vonalkódot adják, de csak alapvető latin karaktereket nyomtatnak a nyomtató saját betűtípusával. Az előnézeti kép pontosan visszaadja a címketervet — a választott betűtípussal, bármilyen nyelven —, ahogy a dedikált címkeszoftverek is.',
