'Label_Height_Mm' => 'Címke magassága (mm)',
'Label_Size_Hint' => 'Egy matrica fizikai mérete a tekercsen. Pontosan egyeznie kell a betöltött címkékkel — hibás méret esetén a nyomtató rossz helyen keresi a rést, így minden címke egyre jobban elcsúszik.',
'Calibrate_Labels' => 'Címkék kalibrálása',
'Calibrate_Labels_Hint' => 'A nyomtató néhány címkét továbbít a matrica és a rés méréséhez. Futtassa egyszer új tekercs behelyezése után, vagy ha a nyomtatási pozíció elcsúszik.',
'Calibration_Sent' => 'A kalibrálás elindult — a nyomtató néhány üres címkét továbbít a méréshez. Ha leáll, futtasson tesztnyomtatást.',
'Label_Printer_Dpi' => 'Nyomtatófej felbontása',
'Label_Printer_Dpi_Hint' => 'A legtöbb címkenyomtató 203 dpi. Nem biztos benne? Használja az alábbi „Felbontás meghatározása” gombot — kinyomtatja a választ.',
'Find_Resolution' => 'Felbontás meghatározása',
'Find_Resolution_Hint' => 'Két címkét nyomtat 203 és 300 jelöléssel. A helyes egy teljes téglalapot mutat a matricán, mind a négy oldalon kis, egyenletes margóval; a hibásról hiányoznak a szegélyek, vagy átlóg a következő matricára.',
'Dpi_Test_Sent' => 'Két címke nyomtatódik 203 és 300 jelöléssel. A helyes egy teljes téglalapot mutat, mind a négy oldalon kis, egyenletes margóval — állítsa a „Nyomtatófej felbontása” értéket erre a számra, és mentsen.',
'Label_Offset_X' => 'Vízszintes eltolás (mm)',
'Label_Offset_X_Hint' => 'Oldalirányban mozgatja a nyomatot a matricán. Akkor használja, ha a szöveg az egyik oldalon levágódik — pl. 2.5, ha a fehér matrica egy szélesebb hordozópapír közepén helyezkedik el. 0.5-ös lépésekben állítsa.',
'Label_Offset_Y' => 'Függőleges eltolás (mm)',
