/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Rendelési útmutató',
'Ord_Guide_Intro' => 'Hogyan jut el egy online áruházban leadott rendelés a készletébe és a könyvelésébe, és hol kerül ténylegesen rögzítésre a pénz.',
'Ord_Guide_Lifecycle_Title' => 'Rendelés állapota',
'Ord_Guide_Lifecycle_Pending' => 'Új rendelés, amely az Ön áttekintésére vár. Csak függőben lévő rendelés erősíthető meg vagy törölhető.',
'Ord_Guide_Lifecycle_Confirmed' => 'Ön elfogadta a rendelést. A Stocky eladást hoz létre a kiválasztott raktárban, és levonja a készletet — ebből az eladásból dolgoznak a készlet-, fizetési és nyereségjelentések.',
'Ord_Guide_Lifecycle_Shipped' => 'Ön feladta a rendelést. Csak teljesítés: a készlet már a megerősítéskor levonásra került.',
'Ord_Guide_Lifecycle_Delivered' => 'A vásárló megkapta a rendelést. Ez indítja el a visszaküldési időszakot.',
'Ord_Guide_Lifecycle_Cancelled' => 'A rendelést a megerősítés előtt elvetették, így nem jött létre eladás, és nem került levonásra készlet.',
'Ord_Guide_PaymentStatus_Tip' => 'Fizetéskor kerül beállításra, itt nem szerkeszthető. Kattintson, hogy megtudja, hogyan rögzítse a fizetést.',
'Ord_Guide_Payment_Title' => 'Fizetési állapot',
'Ord_Guide_Payment_Intro' => 'Ez az oszlop azt rögzíti, hogyan választott fizetni a vásárló a pénztárnál. Az áruház állítja be, és erről az oldalról nem szerkeszthető — magát a pénzt a rendelés megerősítésekor létrejövő eladáson követjük.',
'Ord_Guide_Payment_Paid' => 'A vásárló már online fizetett egy fizetési szolgáltatón keresztül. A rendelés megerősítése Fizetett állapotú eladást hoz létre, és rögzíti Ön helyett a fizetést — nincs más teendő.',
'Ord_Guide_Payment_Pending' => 'Utánvét, banki átutalás vagy más későbbi fizetési mód. A rendelés megerősítése Fizetetlen állapotú eladást hoz létre, így a pénzt Önnek kell rögzítenie, amint beszedte — lásd az alábbi lépéseket.',
'Ord_Guide_Payment_Failed' => 'A fizetési szolgáltató elutasította a fizetést, vagy a vásárló félbehagyta. A rendelés automatikusan törlődik.',
'Ord_Guide_MarkPaid_Title' => 'Fizetés módosítása függőből fizetettre',
'Ord_Guide_MarkPaid_Step1' => 'Először itt erősítse meg a rendelést — a megerősítés hozza létre az eladást.',
'Ord_Guide_MarkPaid_Step2' => 'Nyissa meg az Eladások > Összes eladás menüpontot, és keresse meg az eladást (ugyanaz a vásárló, és a részletek oldal mutatja, melyik online rendelésből származik).',
'Ord_Guide_MarkPaid_Step3' => 'Nyissa meg a sor műveleti menüjét, és válassza a Kifizetés létrehozása lehetőséget.',
'Ord_Guide_MarkPaid_Step4' => 'Adja meg az összeget, a fizetési módot és a dátumot, majd mentsen. Az eladás az összegtől függően automatikusan Részleges vagy Fizetett állapotba kerül.',
'Ord_Guide_MarkPaid_Note' => 'Az itt látható fizetési állapot továbbra is a pénztárnál választott módot rögzíti, és változatlan marad. Az eladás a könyvelési rekord, és ez táplálja a fizetési és nyereségjelentéseket. Az eladás Kifizetések megjelenítése funkciójával tekintheti át vagy szerkesztheti a megadott adatokat.',
'Ord_Guide_Notes_Title' => 'Jó tudni',
'Ord_Guide_Note_Warehouse' => 'A megerősítéskor kiválasztott raktár határozza meg, honnan kerül levonásra a készlet. Azok a raktárak, amelyek nem tudják teljesíteni a teljes rendelést, Nincs készleten jelölést kapnak a listában.',
'Ord_Guide_Note_Preorder' => 'Az előrendelt tételek kihagyják a készletellenőrzést, így az ilyeneket tartalmazó rendelés akkor is megerősíthető, ha a mennyiség még nincs készleten.',
'Ord_Guide_Note_Flagged' => 'A Megjelölt címke azt jelenti, hogy a rendelés fizetéskor csalásgyanús ellenőrzést váltott ki. Vigye az egeret a címke fölé az ok megtekintéséhez, és megerősítés előtt tekintse át a rendelést.',
'Ord_Guide_Note_Cancel' => 'Törlés csak addig lehetséges, amíg a rendelés függőben van. Megerősítés után az eladáson vagy vásárlói visszárun keresztül vonja vissza.',


