'Guide' => 'Útmutató',
'Variants_Guide' => 'Változatok útmutató',
'VG_Intro' => 'A változatos termék több változatként kerül értékesítésre. Építse fel őket opciókból (ajánlott) vagy egyszerű névlistaként. Minden változatnak saját kódja, árai, képe és készlete van.',
'VG_Options_Title' => 'Opciós mód (szín, méret...)',
'VG_Opt_Step1' => 'Hagyja a kártya fejlécében lévő kapcsolót az „Opciók” állásban.',
'VG_Opt_Step2' => 'Írjon be egy opciónevet, például Szín vagy Méret, vagy válasszon egyet a javaslatok közül.',
'VG_Opt_Step3' => 'Írjon be egy értéket (például Piros), és nyomja meg az Entert. Ismételje meg minden értékhez; a vessző is elválasztja az értékeket. Egy érték eltávolításához kattintson rajta az x-re.',
