'VG_Opt_Step5' => 'Kattintson a „Változatok generálása” gombra. Minden kombinációhoz egy sor jön létre, neve automatikusan összeáll, például "Red / S".',
'VG_Opt_Step6' => 'Adja meg a beszerzési és eladási árat minden sorban, vagy írjon be egy értéket az „Alkalmazás mindegyikre” mezőbe, és kattintson a Költség vagy Ár gombra, hogy minden sorba átmásolja.',
'VG_Opt_Step7' => 'A kódok automatikusan generálódnak. Írja be a sajátját, vagy kattintson a frissítés ikonra egy újabb generálásához.',
'VG_Opt_Step8' => 'Opcionális: jelölje be a „Színminták” lehetőséget egy opciónál, és válasszon színt minden értékhez; az áruház színes pöttyként jeleníti meg.',
'VG_Rows_Title' => 'Változatsorok',
'VG_Rows_Text' => 'Minden sorban van kép, kód, vonalkód, beszerzési ár, eladási ár, nagykereskedelmi ár és minimális eladási ár. Termék létrehozásakor minden változathoz megadhatja a raktáronkénti nyitókészletet is. A „Hiányos” címke azt jelenti, hogy a sorból hiányzik egy opció értéke.',
'VG_List_Title' => 'Egyszerű lista mód',
'VG_List_Text' => 'Írjon be egy változatnevet, és nyomja meg az Entert (vagy kattintson a Hozzáadás gombra) egy sor hozzáfűzéséhez, majd töltse ki a kódját és árait. Ez a klasszikus működés, és a meglévő termékeknél továbbra is elérhető.',
'VG_Edit_Title' => 'Későbbi szerkesztés',
'VG_Edit_1' => 'Adjon hozzá egy értéket, és kattintson a „Változatok generálása” gombra: csak a hiányzó kombinációk kerülnek hozzáadásra. A meglévő sorok megtartják kódjaikat, áraikat és előzményeiket.',
'VG_Edit_2' => 'Egy érték vagy opció eltávolítása eltávolítja az azt használó sorokat. A már mentett sorok a termék mentésekor, megerősítés után törlődnek.',
