'Upd_Guide_Before_Title' => '1. Frissítés előtt',
'Upd_Guide_Before_Download' => 'Töltse le az alkalmazás {package} a CodeCanyon-fiókjából ({path}). Ne csomagolja ki – a frissítőnek pontosan a letöltött ZIP-re van szüksége.',
'Upd_Latest_Full_Zip' => 'legfrissebb teljes ZIP-csomagját',
'Upd_Guide_Before_Admin' => 'Győződjön meg róla, hogy olyan rendszergazdaként van bejelentkezve, aki rendelkezik a(z) {perm} jogosultsággal. Senki más nem láthatja és nem futtathatja a frissítőt.',
'Upd_Guide_Before_Quiet' => 'Válasszon csendes időszakot: a frissítés alatt az alkalmazás rövid időre karbantartási módba vált, és a többi felhasználó ki van zárva.',
'Upd_Guide_Before_No_Manual' => 'Önnek {not} kell manuálisan biztonsági mentést készítenie, fájlokat kicsomagolnia, parancsokat futtatnia, konfigurációs fájlokat szerkesztenie vagy az adatbázishoz nyúlnia – a frissítő mindezt automatikusan elvégzi. (Egy plusz manuális biztonsági mentés persze sosem árt.)',
'Upd_Not' => 'nem',
'Upd_Guide_Code_Overwritten' => 'Ha manuálisan módosította az alkalmazás kódját, a frissítés felülírja a módosításait. Az adatai, feltöltései, beállításai és a .env mindig megmaradnak.',
'Upd_Guide_Running_Title' => '2. A frissítés futtatása',
'Upd_Guide_Run_Open' => 'Nyissa meg ezt: {path} (ez az oldal), és maradjon a(z) {tab} lapon.',
'Upd_Guide_Run_Upload' => '{upload}: kattintson vagy húzza a letöltött csomagot a feltöltési mezőbe. A nagy fájlok kis darabokban töltődnek fel, így ez alacsony feltöltési korlátú megosztott tárhelyen is működik. Egy ellenőrzőösszeg véd a sérült vagy hiányos feltöltések ellen.',
'Upd_Upload_The_Zip' => 'A ZIP feltöltése',
'Upd_Guide_Run_Validation' => '{auto} a feltöltés után (a(z) {button} gombbal újra futtatható). A rendszer ellenőrzi: a ZIP sértetlenségét, a csomag szerkezetét és teljességét, a verziókompatibilitást (visszaléptetés nem engedélyezett), a szükséges PHP-verziót és -bővítményeket, a fájljogosultságokat, a szabad lemezterületet, az adatbázis-kapcsolatot, a konfigurációt, valamint azt, hogy nem fut-e másik frissítés.',
'Upd_Validation_Runs_Automatically' => 'Az ellenőrzés automatikusan lefut',
'Upd_Guide_Run_Review' => 'Tekintse át a(z) {panel} panelt. A(z) {button} gomb csak akkor jelenik meg, ha minden kritikus ellenőrzés sikeres. Ha egy ellenőrzés sikertelen, az üzenet pontosan megmondja, mit kell javítani.',
'Upd_Guide_Run_Click' => 'Kattintson a(z) {button} gombra, és erősítse meg. Ezután egyszerűen {keep}, és kövesse a folyamatjelzőt. A rendszer sorrendben a következőket hajtja végre:',
'Upd_Keep_Page_Open' => 'tartsa nyitva ezt az oldalt',
'Upd_Guide_Phase_Backup' => '{label} – teljes adatbázis-mentés, a frissítés által módosítható összes alkalmazásfájl ZIP-archívuma és a(z) {env} másolata jön létre, majd {verified}. A feltöltéseit ({images}) és a(z) {storage} mappát a frissítés soha nem érinti, ezért ezek nem kerülnek archiválásra. Ha a biztonsági mentés nem hozható létre, a frissítés itt leáll, és semmi sem változik.',
'Upd_Verified' => 'ellenőrzésre kerülnek',
'Upd_Guide_Phase_Prepare' => '{label} – az új verzió egy átmeneti területre kerül kicsomagolásra, és ismét ellenőrzésre kerül. Az élő alkalmazás továbbra is érintetlen.',
'Upd_Guide_Phase_Maintenance' => '{label} – a karbantartási mód bekapcsol; a látogatók egy barátságos „Hamarosan visszatérünk” képernyőt látnak.',
'Upd_Guide_Phase_Files' => '{label} – az új fájlok szinte azonnal a helyükre kerülnek; a régi fájlok a visszaállításhoz félre vannak téve. A védett útvonalak ({env}, {storage}, {images}) soha nem kerülnek cserére.',
'Upd_Guide_Phase_Database' => '{label} – lefutnak a migrációk, majd frissülnek a jogosultságok, a fordítások és a sablonok.',
'Upd_Guide_Phase_Cache' => '{label} – minden gyorsítótár törlődik és újraépül.',
'Upd_Guide_Phase_Verify' => '{label} – állapotellenőrzések igazolják, hogy az új verzió elindul, az adatbázis működik, minden migráció lefutott, és a konfiguráció érvényes.',
'Upd_Guide_Phase_Done' => '{label} – a karbantartási mód kikapcsol, és az ideiglenes fájlok törlődnek.',
'Upd_Guide_Run_Success' => 'Amikor ezt látja: {success}, kattintson ide: {reload}, és frissítse a böngészőt a gyorsítótár megkerülésével ({keys}), hogy betöltődjenek az új adminpanel-erőforrások.',
'Upd_Update_Successful_Short' => 'A frissítés sikeres',
'Upd_Guide_No_Internet' => 'A frissítés alatt nincs szükség internetkapcsolatra – minden a feltöltött ZIP-ből származik. A kapcsolat megszakadása vagy a böngésző bezárása NEM rontja el a frissítést: a szerver pontosan megjegyzi, hol állt meg.',
'Upd_Guide_Wrong_Title' => '3. Ha valami elromlik',
'Upd_Guide_Wrong_Rollback' => '{label} – ha bármi meghiúsul azután, hogy a fájlok módosítása elkezdődött (kicsomagolási hiba, sikertelen migráció, sikertelen állapotellenőrzés, megtelt lemez, …), a rendszer automatikusan visszaállítja a korábbi fájlokat és az adatbázist az ellenőrzött biztonsági mentésből, kikapcsolja a karbantartási módot, és ezt jelzi: {message}. Pontosan oda kerül vissza, ahonnan indult.',
'Upd_Automatic_Rollback' => 'Automatikus visszaállítás',
'Upd_Failed_Previous_Restored' => 'A frissítés sikertelen – a korábbi verzió visszaállítva',
'Upd_Guide_Wrong_Interrupted' => '{label} (szerver-újraindítás, időtúllépés, bezárt böngésző, áramkimaradás) – amikor újra megnyitja ezt az oldalt, egy piros sáv két biztonságos lehetőséget kínál: {resume} (pontosan attól a lépéstől folytatja, ahol megállt) vagy {rollback} (visszaállítja a korábbi verziót a biztonsági mentésből).',
'Upd_Interrupted_Update' => 'Megszakadt frissítés',
'Upd_Guide_Wrong_Unreachable' => '{label} – használja az önálló {console} felületet itt: {path}. Akkor is működik, ha a webhely karbantartási módban van vagy az adminpanel erőforrásai hibásak, és ugyanazokat a Folytatás / Visszaállítás műveleteket kínálja. A karbantartási képernyő alján egy diszkrét „Rendszergazdai hozzáférés” link is található.',
'Upd_Admin_Unreachable' => 'Az adminpanel nem érhető el',
'Upd_Recovery_Console' => 'helyreállítási konzol',
'Upd_Guide_Wrong_Locked_Out' => '{label} – amíg egy frissítés fut, ez az oldal megjelenít egy hivatkozást: {link}. Mentse el, ha vissza kell jutnia (például ha lejárt a munkamenete); ezzel átjuthat a karbantartási képernyőn, és újra bejelentkezhet.',
'Upd_Locked_Out_Maintenance' => 'Kizárva a karbantartási mód miatt',
'Upd_Bypass_Link' => 'megkerülő link',
'Upd_Guide_Wrong_Concurrent' => '{label} – ezt fogja látni: {message} Egyszerre mindig csak egy frissítés futhat.',
'Upd_Another_Admin_Updating' => 'Egy másik rendszergazda egyszerre próbál frissíteni',
'Upd_Guide_Backups_Title' => '4. Biztonsági mentések és visszaállítás',
'Upd_Guide_Backups_Created' => 'Minden frissítés biztonsági mentést készít, {before} bármihez hozzányúlna: az összes alkalmazásfájlról, amelyet a frissítés lecserélhet, a(z) {env} másolatáról és egy teljes adatbázis-mentésről. A feltöltéseket és a(z) {storage} mappát a frissítés soha nem módosítja, ezért ezek nem részei a mentésnek – ezekről készítsen saját biztonsági mentést. A biztonsági mentések itt találhatók: {path}, és a webről soha nem érhetők el.',
'Upd_Before' => 'mielőtt',
'Upd_Guide_Backups_Panel' => 'A(z) {tab} lapon lévő {panel} panel dátummal, verzióval és mérettel listázza őket. Innen bármely teljes biztonsági mentést {restore} (fájlok + adatbázis – előtte biztonsági másolat készül az aktuális adatbázisról), vagy {delete} a régieket.',
'Upd_Restore_Verb' => 'visszaállíthat',
'Upd_Delete_Verb' => 'törölheti',
'Upd_Guide_Backups_Retention' => 'A(z) {keep} beállítással választhatja ki, hány biztonsági mentés maradjon meg; a régebbiek minden sikeres frissítés után automatikusan törlődnek. Az egyetlen megmaradt teljes biztonsági mentés soha nem törölhető – mindig marad visszaút.',
'Upd_Guide_Manual_Title' => '5. Manuális frissítés (tartalék módszer)',
'Upd_Guide_Manual_Text' => 'Ha inkább kézzel frissítene, vagy a feltöltő nem használható a szerverén, kövesse az oldal {tab} lapján található lépésenkénti útmutatót.',
'Upd_Guide_Clear_Cache_First' => 'Ha bármely frissítés után az oldalak hibásan vagy üresen jelennek meg, először törölje a böngésző gyorsítótárát – szinte mindig ez az oka.',
'Upd_Restore_Backup_Confirm' => 'Visszaállítja ezt a biztonsági mentést? Az aktuális fájlokat és az aktuális adatbázist a biztonsági mentés váltja fel. Előtte biztonsági másolat készül az aktuális adatbázisról. (v{version} – {date})',
'Woo_Guide_Lead' => 'Hogyan marad összhangban egy WooCommerce-áruház az ERP-vel. Az alábbi cron sorok erre a szerverre készültek, így közvetlenül átmásolhatók rá.',
'Woo_Guide_Ways_Note' => 'A Shopifyjal ellentétben a WooCommerce magától semmit sem küld az ERP-nek – itt nincs webhook-fogadó, így minden {in} irányú adat ütemezve érkezik. Csak a {out} irányú készlet lehet azonnali.',
'Woo_In' => 'befelé',
'Woo_Out' => 'kifelé',
'Woo_Guide_Both_Ways_Title' => 'Mindkét irányhoz először ez kell',
'Woo_Api_Keys' => 'API-kulcsok',
'Woo_Guide_Api_Keys_Text' => '{path}, jogosultság: {perm}. Másolja a fogyasztói kulcsot és titkot a(z) {settings} lapra az áruház URL-jével együtt – a webhelye címe záró perjel nélkül, pl. {example}.',
'Woo_Credentials_Saved' => 'hitelesítő adatok mentve',
'Woo_Not_Configured_Yet' => 'még nincs beállítva',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-alkalmazásjelszó (nem kötelező)',
'Woo_Guide_Wp_App_Password_Text' => 'Csak a termékképekhez használatos. A WooCommerce API mozgatja a termékeket, a készletet, a kategóriákat, a márkákat, az ügyfeleket és a megrendeléseket; a WordPress API az, amely a Médiatárban keres, és feltölti a még ott nem lévő képeket.',
'Woo_Guide_Wp_App_Password_Note' => 'Használjon médiakezelési jogosultsággal rendelkező WordPress-felhasználót, és hozza létre a jelszót itt: {path}. Ha mindkét mezőt üresen hagyja, minden szinkronizálódik – csak a képek csatolása marad ki.',
'Woo_Guide_Pick_Way_Title' => 'Ezután válassza ki, hogyan maradjon összhangban',
'Woo_Right_Away' => 'Azonnal',
'Woo_Stock_Live' => 'élő készlet',
'Woo_Stock_Not_Live' => 'nem élő készlet',
'Woo_Guide_Realtime_Lead' => 'Csak egy irány: az ERP-ből kimenő készlet és termékek. A WooCommerce-ben végzett megrendelések és termékmódosítások továbbra is ütemezve érkeznek – lásd a másik lapot.',
'Woo_Push_Stock_On_Change' => 'Készlet küldése a változás pillanatában',
'Woo_Setting_People_Miss' => 'Ezt a beállítást szokták kihagyni',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Egy POS-értékesítés magától {not} el a WooCommerce-hez. Kikapcsolva az áruház csak a következő készletszinkronizáláskor értesül róla – alapértelmezés szerint egy óra múlva –, és ebben az időablakban eladhat egy olyan egységet, amelyet a pénztárnál már eladott.',
'Woo_Does_Not' => 'nem jut',
'Woo_Guide_Tick_Instant' => 'Jelölje be a(z) {option} lehetőséget a(z) {settings} lapon. Ez a teljes beállítás – nincs feldolgozó, nincs cron. Ezután minden értékesítés, visszáru, korrekció, átvezetés és beérkezett beszerzés csak az érintett termékekről küld frissítést, közvetlenül az értékesítés mentése után, és egy húszsoros értékesítés egyetlen küldés, nem húsz. A pénztár sosem vár rá.',
'Woo_Currently' => 'Jelenleg:',
'Woo_Instant_On_Text' => 'be – a készlet változáskor kerül küldésre',
'Woo_Instant_Off_Text' => 'ki – a készlet csak ütemezve',
'Woo_Guide_Instant_Note' => 'Csak a WooCommerce-hez már kapcsolt termékek kerülnek küldésre – egy soha nem szinkronizált terméknek nincs mit javítania az áruházban. A variálható termékek a szülőjükön keresztül mennek, a kombinált termék pedig újra elküldésre kerül, ha bármely összetevője mozog. A tömeges műveletek (termék törlése, raktár alaphelyzetbe állítása) esemény kiváltása nélkül írják a készletet, ami az egyik ok arra, hogy az óránkénti készletszinkronizálást is megtartsa.',
'Woo_Push_Products_On_Save' => 'Termékek küldése a mentés pillanatában',
'Woo_Guide_Tick_Auto_Products' => 'Jelölje be a(z) {option} lehetőséget a(z) {settings} lapon, és a Stockyban létrehozott, szerkesztett vagy duplikált termék közvetlenül a mentés után a WooCommerce-be kerül – adatok, ár, változatok és képek, majd a készlete. Az új termék azonnal létrejön az áruházban, ahelyett hogy az éjszakai termékszinkronizálásra várna.',
'Woo_On' => 'be',
'Woo_Off' => 'ki',
'Woo_Guide_Bulk_Imports_Note' => 'A tömeges importok nem kerülnek egyenként küldésre – import után futtasson termékszinkronizálást. Először a kategóriákat és márkákat szinkronizálja, hogy a küldött termék a megfelelő kategóriába kerüljön.',
'Woo_Nothing_Else_To_Install' => 'Mást nem kell telepíteni',
'Woo_Guide_Same_Process' => 'Nincs sorfeldolgozó, nincs cron-bejegyzés. A küldés ugyanabban a folyamatban fut, amely az értékesítést kiszolgálta, {after} a válasz már visszament, így a pénztár sosem vár a WooCommerce-re. A küldések soha nem fedik át egymást: a futás közben történt módosítások megvárják, és közvetlenül utána mennek ki.',
'Woo_After' => 'miután',
'Woo_Guide_Shop_Stops_Answering' => 'A nem válaszoló áruházzal nyolc másodperc után feladja a próbálkozást, és a küldések öt percre szünetelnek, hogy ne várjon rá ismét minden értékesítés; az időközben beérkezett módosítások a szünet utáni első küldéssel mennek ki, az óránkénti készletszinkronizálás pedig mindenképp pótolja őket. Minden szünet rögzítésre kerül a Naplók lapon.',
'Woo_Guide_Artisan_Exception' => 'Egy kivétel: az artisan parancs által végzett készletváltozásnak nincs válasza, amely után futhatna, ezért helyette a(z) {queue} sorba kerül. Ha azt szeretné, hogy ezek is gyorsan kimenjenek, dolgozza fel ezt a sort:',
'Woo_Cron_Line_Copied' => 'Cron sor másolva',
'Woo_Command_Copied' => 'Parancs másolva',
'Woo_Guide_Not_Woo_Queue' => 'Szándékosan nem a(z) {queue} sor: az az órákig tartó katalóguskötegeket viszi, és egy mögé sorolt azonnali küldés nem lenne azonnali.',
'Woo_On_A_Schedule' => 'Ütemezve',
'Woo_Guide_Scheduled_Lead' => 'Időnként minden újraellenőrzésre kerül, mindkét irányban. Így jutnak el a megrendelések az ERP-be, így kerül közzétételre a katalógus, és ez javít ki mindent, amit a gyors út kihagyott. Minden feladat saját cron-bejegyzést kap, így csak azt futtatja, amit szeretne.',
'Woo_Guide_Sync_Drains_Queue' => 'A(z) {command} futás közben feldolgozza a saját sorát, így ezekhez a sorokhoz nem kell külön feldolgozó. Windows rendszeren használja a Feladatütemezőt a(z) {program} programmal és ugyanazokkal az argumentumokkal, indítási könyvtárként: {path}.',
'Woo_Or_No_Cron' => 'Vagy egyáltalán nincs cron',
'Woo_Guide_No_Cron_Text' => 'Itt minden lap igény szerint szinkronizál, és a manuális szinkronizálás feldolgozza a saját kötegeit, amíg az oldal nyitva van – így egy kis áruház cron-bejegyzés nélkül is működhet. Amit elveszít: mindazt, ami akkor történik, amikor senki sem figyel – a megrendelések csak akkor érkeznek, ha valaki megnyomja a gombot.',
'Woo_Commands_Worth_Knowing' => 'Hasznos parancsok',
'Woo_Worth_Knowing' => 'Érdemes tudni',
'Woo_Guide_Changing_Url_Clears' => 'Az áruház URL-jének vagy az API-kulcsoknak a módosítása minden megfeleltetést töröl – a termékek, kategóriák, márkák és ügyfelek mind újra szinkronizálódnak az új áruházzal.',
'Woo_Guide_Keep_Skus' => 'Tartsa egységesen a cikkszámokat (SKU) a Stocky és a WooCommerce között: ez akadályozza meg a duplikátumokat, és ez teszi biztonságossá az újrakapcsolást.',
'Woo_Guide_Stock_Total' => 'A Woo-ba közzétett készlet {total}, nem egyetlen raktár adata.',
'Woo_Total_Across_Warehouses' => 'az összes raktár együttes készlete',
