'Woo_Settings_Instant_Hint' => 'Egy értékesítés, visszáru vagy korrekció a mentés pillanatában készletfrissítést küld csak az érintett termékekről, így az áruház másodperceken belül naprakész, nem csak a következő óránkénti készletszinkronizáláskor. Mást nem kell telepíteni – a küldés az értékesítés megválaszolása után fut, így a pénztár sosem vár a WooCommerce-re. Bővebben a(z) {guide} lapon.',
'Woo_Settings_Instant_Off_Alert' => 'Ha kikapcsolva hagyja, egy POS-értékesítés csak a következő készletszinkronizáláskor jut el a WooCommerce-hez – akár egy órával később.',
'Woo_Settings_Auto_Products_Hint' => 'A Stockyban létrehozott, szerkesztett vagy duplikált termék közvetlenül a mentés után a WooCommerce-be kerül – adatok, ár, változatok, képek, majd a készlete –, ahelyett hogy termékszinkronizálásra várna. A tömeges importok nem kerülnek küldésre; import után futtasson termékszinkronizálást.',
'Woo_Sync_Tuning' => 'Szinkronizálás finomhangolása',
'Woo_Sync_Tuning_Intro' => 'Az alapértelmezések a legtöbb áruháznak megfelelnek. Csak akkor módosítsa ezeket, ha a szinkronizálás lassú, vagy időtúllépés történik a tárhelyén. Minden érték biztonságos tartományra van korlátozva, és egy mező törlése visszaállítja az alapértelmezést.',
'Woo_Setting_This_Up' => 'Beállítás',
'Woo_Setting_This_Up_Text' => 'Az API-kulcsok beszerzése, mire szolgál a WordPress-alkalmazásjelszó, az ütemezett szinkronizálások cron-bejegyzései, és hogyan juthat el a készlet az áruházba a változás pillanatában – mindez az Útmutató lapon található, a szerver saját, másolásra kész cron soraival. Egyetlen példány, így nem térhet el attól, amit a modul ténylegesen csinál.',
