'Presta_Guide_4' => 'Először húzza le a termékeket, ha az áruháznak már van katalógusa (hivatkozás/SKU alapján felelteti meg); a küldés létrehozza a hiányzó egyszerű termékeket.',
'Presta_Guide_5' => 'Küldje el a készletet, valahányszor a mennyiségek változnak, és rendszeresen húzza le a megrendeléseket – a PrestaShop nem rendelkezik webhookokkal, így a megrendelések csak lehúzáskor érkeznek.',
