'Shopify_Stock_Lag_Desc' => 'A pultnál történt értékesítés addig láthatatlan marad az áruház számára – akár {n} percig, így az utolsó egység online még kétszer is eladható. Kapcsolja be ezt: {setting}, és ehelyett minden értékesítés, visszáru és korrekció másodperceken belül elküldésre kerül.',
'Shopify_Turn_It_On' => 'Bekapcsolás',
'Shopify_Stock_Also_Pushed' => 'A készlet bármely értékesítés, visszáru vagy korrekció után másodperceken belül is kiküldésre kerül, anélkül hogy a fenti lépésre várna.',
'Shopify_Sync_History' => 'Szinkronizálási előzmények',
'Shopify_Nothing_Run_Store' => 'Ennél az áruháznál még semmi sem futott',
'Shopify_Hook_Msg_Client' => 'Kattintson az alábbi „Webhookok regisztrálása” gombra – a Shopifyban semmit sem kell megadni.',
'Shopify_Hook_Msg_Token' => 'Kattintson az alábbi „Webhookok regisztrálása” gombra, és illessze be az alkalmazás API secret key értékét az áruház beállításaiba aláírási titokként.',
'Shopify_Hook_Note_Register' => 'A regisztráció létrehozza a feliratkozásokat a Shopifyban, és automatikusan erre a címre irányítja őket. Ne adja hozzá kézzel a Shopify → Settings → Notifications → Webhooks alatt: azok más titokkal vannak aláírva, és minden kézbesítés elutasításra kerülne.',
'Shopify_Hook_Verified_Client' => 'A kézbesítések az alkalmazás client secretjével kerülnek ellenőrzésre, amely már tárolva van.',
'Shopify_Hook_Signature_Required' => 'Az érvényes aláírás nélküli kézbesítések elutasításra kerülnek, ezért a titkot be kell állítani, mielőtt a webhookok bármit tennének.',
'Shopify_Hook_Retries' => 'A Shopify addig próbálkozik, amíg 2xx választ nem kap, és minden kézbesítés egyszer kerül rögzítésre – az ismételt esemény nem csinál semmit, nem keletkezik duplikált megrendelés.',
'Shopify_No_Signing_Secret' => 'Nincs tárolt aláírási titok',
'Shopify_No_Signing_Secret_Desc' => 'Feliratkozások létrehozhatók nélküle is, de minden kézbesítés elutasításra kerül, amíg az alkalmazás API secret key értéke nincs elmentve ennél az áruháznál (egy Dev Dashboard-alkalmazás client secretje ezt már lefedi).',
'Shopify_Register_In_Shopify' => 'Regisztrálás a Shopifyban',
'Shopify_Refresh_List' => 'Lista frissítése',
