'Shopify_Sub_Removed' => 'Feliratkozás eltávolítva',
'Shopify_Could_Not_Remove_Sub' => 'Nem sikerült eltávolítani ezt a feliratkozást',
'Shopify_Could_Not_Load_Store' => 'Nem sikerült betölteni ezt az áruházat',
'Shopify_G_Lead_Store' => 'Mire van szüksége ennek az áruháznak ahhoz, hogy összhangban maradjon. Minden itt szereplő adat erre az áruházra vonatkozik – az útvonalak és azonosítók valósak, így a parancsok közvetlenül átmásolhatók a szerverre.',
'Shopify_G_Lead_Generic' => 'Hogyan marad összhangban egy Shopify-áruház az ERP-vel. Válasszon fent egy áruházat a saját állapotának megtekintéséhez, vagy olvassa így – a cron sor és a webhook URL ugyanaz, bármelyik áruházat is csatlakoztatja.',
'Shopify_G_Ways_Note' => 'A legtöbb áruház mindkettőt futtatja: az első percről percre naprakészen tartja az áruházat, a második pótolja, amit az első kihagyott – egy meg nem érkezett webhookot, egy közvetlenül a Shopify adminfelületén végzett módosítást, egy éjszakát, amikor a webhely nem működött.',
'Shopify_G_Both_Need' => 'Mindkét irányhoz először ez kell',
'Shopify_G_Credentials' => 'Shopify hitelesítő adatok',
'Shopify_G_Cred_Intro' => '2026 januárja óta a Shopify már nem hoz létre egyéni alkalmazásokat az adminfelületen belül, így kétféle kapcsolat létezik:',
'Shopify_G_Cred_DevDash' => '{app} (bármely most csatlakoztatott áruház) – {path}. Adja meg az Admin API hatóköreit ahhoz, amit ez az áruház szinkronizál, telepítse az alkalmazást az áruházba, majd másolja a(z) {clientId} és {clientSecret} értékét az alkalmazás Settings oldaláról ide: {where}. Az ERP ezeket maga cseréli hozzáférési tokenre, és 24 óránként, lejárat előtt megújítja. A client secret a webhookokat is aláírja, így másra nincs szükség. Az alkalmazásnak és az áruháznak ugyanabban a Shopify-szervezetben kell lennie.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard-alkalmazás',
'Shopify_G_Cred_Legacy' => '{app} (2026 előtt az adminfelületen létrehozva) – változatlanul működik tovább a saját {token} értékével ({prefix}) és a(z) {secret} értékével mint webhook-aláírási titokkal. Ez nem ugyanaz az érték, mint a token, és ezek felcserélése a webhookok elutasításának szokásos oka.',
'Shopify_G_Legacy_App' => 'Régi egyéni alkalmazás',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'tárolva',
'Shopify_G_Missing_Refused' => 'hiányzik – a kézbesítések elutasításra kerülnek',
'Shopify_G_Where_Data_Desc' => '{path} Az ERP-raktár, amelynek készletét ez az áruház értékesíti, és a Shopify-helyszín, ahová ez a készlet íródik. A készletszinkronizálás és a megrendelésimport sem fut nélkülük.',
'Shopify_G_Currently' => 'Jelenleg: raktár {warehouse}, helyszín {location}',
'Shopify_G_Not_Set_Lower' => 'nincs beállítva',
'Shopify_G_Ready' => 'kész',
'Shopify_G_Incomplete' => 'hiányos',
'Shopify_G_Manual_Syncs' => 'Kézzel indított szinkronizálások',
'Shopify_G_Manual_Desc' => 'A(z) {centre} felületről indított szinkronizálás azonnal válaszol, és a háttérben fut, rövid szeletekben, amelyek mindegyike ott folytatja, ahol az előző abbahagyta. Egy nagy katalógust soha nem szakít meg félúton a hosszú webes kéréseket lezáró tárhely (LiteSpeed, nginx, terheléselosztó), és az oldal bezárása sem állítja le. Ehhez a feldolgozóhoz még egy cron sor kell:',
'Shopify_G_Cron_Copied' => 'Cron sor másolva',
'Shopify_G_Manual_Note' => 'Enélkül is befejeződik a szinkronizálás, de csak amíg a Szinkronizálási központ oldala nyitva marad: ha néhány másodpercen belül egyetlen feldolgozó sem veszi fel a futtatást, maga az oldal viszi tovább, egyszerre egy rövid kéréssel. Windows rendszeren használja a Feladatütemezőt percenként: program: {program}, argumentumok: {args}, indítási könyvtár: {dir}.',
'Shopify_G_Then_Pick' => 'Ezután válassza ki, hogyan maradjon összhangban',
'Shopify_G_Right_Away' => 'Azonnal',
'Shopify_G_Stock_Live' => 'élő készlet',
'Shopify_G_Stock_Not_Live' => 'nem élő készlet',
'Shopify_G_Realtime_Lead' => 'Minden módosítás azonnal, másodperceken belül elküldésre kerül. Két fele van, és ezek külön kapcsolók: a {webhooks} behozzák az áruház saját eseményeit, az {push} pedig kiküldi a készletet.',
'Shopify_G_Webhooks_Lower' => 'webhookok',
'Shopify_G_Instant_Push_Lower' => 'azonnali készletküldés',
'Shopify_G_Webhooks_In' => 'Webhookok – az áruház → az ERP',
'Shopify_G_Webhooks_Desc' => 'Megrendelések, megrendelési állapotváltozások, valamint a Shopifyban végzett termék-, ügyfél- és készletmódosítások. Nyissa meg az áruházat, és nyomja meg a(z) {button} gombot a {tab} – kétszer is nyugodtan megnyomható. A Shopify ide küld:',
'Shopify_G_Webhooks_Tab' => 'Webhookok lapján',
'Shopify_G_Webhooks_Note' => 'A címnek az internetről HTTPS-en keresztül elérhetőnek kell lennie – a Shopify nem kézbesít {localhost} vagy {test} domainre. Minden kézbesítés egyszer kerül rögzítésre, így a Shopify újrapróbálkozásai nem hozhatnak létre duplikált megrendelést, a sikertelen kézbesítés pedig újrajátszható. A kézbesítések elutasításra kerülnek, amíg az 1. lépésben szereplő aláírási titok nincs tárolva.',
'Shopify_G_Instant_Out' => 'Azonnali készletküldés – az ERP → az áruház',
'Shopify_G_Setting_Missed' => 'Ezt a beállítást szokták kihagyni',
'Shopify_G_Pos_Not_Auto' => 'Egy POS-értékesítés magától {not} jut el a Shopifyhoz. Kikapcsolva az áruház csak a következő készletküldési lépéskor értesül róla – és ebben az időablakban eladhat egy olyan egységet, amelyet a pénztárnál már eladott.',
'Shopify_G_Not' => 'nem',
'Shopify_G_Tick_Push' => 'Jelölje be ezt: {setting}, itt: {where}. Ez a teljes beállítás – nincs feldolgozó, nincs cron. Ezután minden értékesítés, visszáru és korrekció csak az érintett termékekről küld frissítést, közvetlenül az értékesítés mentése után, és egy húszsoros értékesítés egyetlen küldés, nem húsz. A pénztár sosem vár rá.',
'Shopify_G_This_Store' => 'Ez az áruház:',
'Shopify_G_Push_On' => 'be – a készlet változáskor kerül küldésre',
'Shopify_G_Push_Off' => 'ki – a készlet csak ütemezve',
'Shopify_G_Push_Note' => 'Csak a már Shopify-megfeleltetéssel rendelkező termékek és csak az áruház raktárában történt mozgások kerülnek küldésre. A tömeges műveletek – termék törlése, raktár alaphelyzetbe állítása – esemény kiváltása nélkül írják a készletet, ami az egyik ok arra, hogy az ütemezett készletlépést is megtartsa.',
'Shopify_G_Nothing_Install' => 'Mást nem kell telepíteni',
'Shopify_G_No_Worker_Note' => 'Egyik félhez sem kell sorfeldolgozó vagy cron-bejegyzés. A bejövő webhook a Shopify által indított kérésben kerül feldolgozásra; a kimenő készletküldés ugyanabban a folyamatban fut, amely az értékesítést kiszolgálta, {after} a válasz már visszament – így a pénztár sosem vár a Shopifyra, a nem válaszoló áruházzal pedig tíz másodperc után feladja, és a következő ütemezett készletküldésre bízza.',
'Shopify_G_After' => 'miután',
'Shopify_G_Artisan_Note' => 'Egy kivétel: az artisan parancs által végzett készletváltozásnak nincs válasza, amely után futhatna, ezért helyette a(z) {queue} sorba kerül. Ha azt szeretné, hogy ezek is gyorsan kimenjenek, dolgozza fel ezt a sort:',
'Shopify_G_On_Schedule' => 'Ütemezve',
'Shopify_G_On_Lower' => 'be',
'Shopify_G_Off_Lower' => 'ki',
'Shopify_G_Scheduled_Lead' => 'Időnként minden újraellenőrzésre kerül, mindkét irányban. Lassabb a valós idejűnél, de ez küldi ki a készletet az azonnali küldést nem használó áruházakban, ez pótolja az elmaradt webhookot, és csak így mozgatható egy teljes katalógus.',
'Shopify_G_Cron_Entry' => 'A cron-bejegyzés',
'Shopify_G_Cron_Entry_Desc' => 'Nélküle semmi ütemezett nem fut. Egy sor, csak ehhez a modulhoz – adja hozzá a többi, ütemezésre kiválasztott elem mellé:',
'Shopify_G_Cron_Note' => 'Az öt perc a legfinomabb felbontás, amelyet egy terv használhat, mert az öt perc a legrövidebb lépésidőköz. Egy durvább bejegyzés egyszerűen alsó határrá válik – {example} esetén az 5 percre állított lépés 15 percenként fut. Windows rendszeren használja a Feladatütemezőt: program: {program}, argumentumok: {args}, indítási könyvtár: {dir}.',
'Shopify_G_Switch_On_Plan' => 'Kapcsolja be, és válassza ki a tervet',
'Shopify_G_Plan_Desc' => '{where} A kapcsoló dönti el, hogy a cron egyáltalán működhet-e; a terv dönti el, mit csinál. Egy {step} egy entitás egy irányban, saját időközzel – {first}, {second}. Az alapértelmezett időközt minden olyan lépés használja, amelynek saját mezője üres.',
'Shopify_G_Step_Lower' => 'lépés',
'Shopify_G_Plan_Note' => 'Ha a tervet üresen hagyja, az áruház az alapértelmezett időközzel húzza le a megrendeléseket és küldi ki a készletet, ami a legtöbb áruháznak megfelel. A megrendelések csak lehúzhatók: a vásárló a Shopifyban adja le őket.',
'Shopify_G_Schedule_On' => 'ütemezés be',
'Shopify_G_Schedule_Off' => 'ütemezés ki – csak kézi',
'Shopify_G_When_Step_Runs' => 'Mikor fut ténylegesen egy lépés',
'Shopify_G_When_Note' => 'Egy lépés akkor esedékes, ha ugyanez a lépés utoljára az időközénél régebben {started}, a futási előzmények alapján. Így a kézzel indított szinkronizálás elhalasztja a következő automatikusat, a folyamatosan sikertelen lépés pedig az időköze szerint kerül újrapróbálásra, nem minden ütemben. Az áruház Áttekintés oldala minden lépés utolsó futását, következő esedékességét, valamint – ha blokkolva van – a blokkolás okát mutatja. Az első katalógusküldést futtassa kézzel – előbb {dryRun} módban –, mielőtt ütemezésre állítaná.',
'Shopify_G_Started_Lower' => 'indult el',
'Shopify_G_Where_Setting' => 'Hol található az egyes beállítás',
'Shopify_G_Where_Setting_Note' => 'Ezek mind egy meglévő áruháznál találhatók: {path}, majd a ceruza ikon (vagy {edit} az áruház saját oldalán).',
'Shopify_G_Product_Images' => 'Termékképek',
'Shopify_G_Img_1' => 'A képek a termékkel együtt mennek ki {push} – először a fő kép, majd a galéria, majd változatonként egy, ha a változatnak sajátja van, legfeljebb ötven.',
'Shopify_G_Products_Push' => 'termékküldéskor',
'Shopify_G_Img_2' => 'A változat képe a termékkel együtt kerül feltöltésre, majd {assigned}, ahogyan a Shopify modellezi: a változat a termék egyik képére mutat. A fő képet újrahasznosító változat nem tölti fel kétszer.',
'Shopify_G_Assigned' => 'hozzárendelésre kerül az adott változathoz',
'Shopify_G_Img_3' => 'A fájlként tárolt kép {uploaded} a Shopifyba, nem linkként, így akkor is működik, ha ez a telepítés nem érhető el az internetről. A beillesztett linkként hozzáadott kép URL-ként kerül átadásra a Shopifynak, ezért annak nyilvánosan elérhetőnek kell lennie.',
'Shopify_G_Uploaded' => 'feltöltésre kerül',
'Shopify_G_Img_4' => 'Csak akkor kerülnek újraküldésre, ha ténylegesen változnak – a csak árat módosító küldés érintetlenül hagyja az áruház képeit, mert elküldésük a teljes készletet lecseréli.',
'Shopify_G_Img_5' => 'Ha az ERP-ben eltávolít egy képet, az a Shopifyban {not} törlődik. Törölje ott is, különben az áruház továbbra is megjeleníti.',
'Shopify_G_Commands' => 'Hasznos parancsok',
'Shopify_G_Command_Copied' => 'Parancs másolva',
'Shopify_G_Foot' => 'Minden szinkronizálás ide ír: {logs}, és minden áruház Áttekintés oldala megmutatja, mikor futott utoljára az egyes lépés, mikor esedékes legközelebb, és mi blokkolja, ha valami blokkolja. Először itt érdemes keresni, ha egy szinkronizálás nem azt tette, amit várt.',
'Shopify_G_Covers' => 'Lefedi',
'Shopify_G_Covers_Rt' => 'A Shopifyban végzett megrendelések és módosítások; az ERP-ből kimenő készlet (POS-értékesítés, visszáru, korrekció)',
'Shopify_G_Covers_Sch' => 'Minden, mindkét irányban – beleértve a katalógusküldéseket és mindazt, amit a gyors út kihagyott',
'Shopify_G_Speed' => 'Sebesség',
'Shopify_G_Speed_Rt' => 'Másodpercek',
