'Cr_Guide_Good_To_Know' => 'Jó tudni',
'Cr_Guide_Webhooks' => 'Webhook címek',
'Cr_Guide_How' => 'Regisztráció módja',
'Cr_Guide_How_It_Works' => 'Hogyan működik',
'Cr_Guide_Meaning' => 'Jelentés',
'Cr_Guide_T_Statuses' => 'Állapotok',
'Cr_Guide_Statuses_Note' => 'Az állapotok csak előre haladnak, így egy késve érkező frissítés soha nem állítja vissza a csomagot. Egy kézbesített csomag ettől még jelenthető visszaúton lévőként vagy visszaküldöttként.',
'Cr_Guide_S_booked' => 'A rendelés a futárnál van; még senki nem vette át. A foglalás csak ekkor mondható le.',
'Cr_Guide_S_picked_up' => 'A futár átvette a csomagot.',
'Cr_Guide_S_in_transit' => 'Elosztóközpontok között, vámkezelés alatt vagy visszatartva.',
'Cr_Guide_S_out_for_delivery' => 'Ma a kézbesítőnél van.',
'Cr_Guide_S_failed_attempt' => 'A címzett nem volt otthon, megtagadta az átvételt, vagy hibás a cím. A futár újra próbálkozik, vagy visszaküldi.',
'Cr_Guide_S_delivered' => 'Átadva a vásárlónak. Az utánvét összege a futár által beszedettnek minősül.',
'Cr_Guide_S_returning' => 'Úton visszafelé Önhöz.',
'Cr_Guide_S_returned' => 'Visszaérkezett Önhöz: az Áttekintendő visszaküldések között várakozik, vagy automatikusan visszakerül a készletbe.',
'Cr_Guide_S_cancelled' => 'A foglalást lemondták.',
'Cr_Guide_T_Booking' => 'Rendelések foglalása',
'Cr_Guide_B_Booking' => 'Az Átadás futárnak az eladás adataiból tölti ki az űrlapot: címzett, cím, a még fennálló tartozás utánvétként, valamint a termékek súlya. A saját városlistával rendelkező futároknál választó jelenik meg, és a választását az adott városra megjegyezzük. Az aggregátorok, a DHL, a FedEx, a UPS és a Lalamove kínálják a Díjak összehasonlítása lehetőséget: válasszon egy árat, és a Foglalás megvásárolja azt. Az eladások listájáról egyszerre több eladás is lefoglalható.',
'Cr_Guide_T_Cod' => 'Utánvét',
'Cr_Guide_B_Cod' => 'Egy utánvétes csomag állapota a „Nincs beszedve” értékről „A futár beszedte” (kézbesítéskor), majd „Kifizetve Önnek” értékre változik. A kifizetéseket jelentő futároknál az utolsó lépés automatikusan megtörténik; a többinél használja az Utánvét frissítése funkciót. Ha a Futárbeállításokban ki van választva egy számla, a kifizetés fizetésként rögzül az eladáson. A futárdíjak a csomag lezárása után költségként menthetők.',
'Cr_Guide_T_Returns' => 'Visszaküldött csomagok',
'Cr_Guide_B_Returns' => 'Alapértelmezés szerint a visszaküldött csomag a Futárküldemények oldalon, az Áttekintendő visszaküldések között várakozik. A Visszavételezés eladási visszárut hoz létre a teljes rendelésre, és a tételeket visszateszi a készletbe; az Elvetés semmit nem tesz vissza, ez sérült vagy elveszett csomagokhoz való. A Futárbeállításokban ehelyett automatikus visszavételezés is beállítható.',
'Cr_Guide_T_Customers' => 'Vásárlói üzenetek és nyomkövetési oldal',
'Cr_Guide_B_Customers' => 'A Futárbeállításokban található vásárlói értesítések SMS-t, e-mailt vagy WhatsApp-üzenetet küldenek a bejelölt állapotoknál, csomagonként egyszer, az Ön saját szövegével. Az online áruház nyomkövetési oldalán a vásárlók nyomkövetési számmal, vagy rendelésszámmal és telefonszámmal követhetik a csomagot. A gyakran csomagot visszaküldő vásárlók foglaláskor visszaküldési kockázat jelölést kapnak.',
'Cr_Guide_T_Labels' => 'Címkék',
'Cr_Guide_B_Labels' => 'A Címke nyomtatása a futár saját címkéjét adja, ha az kiállít ilyet (PDF, hivatkozás vagy kép), ellenkező esetben Stocky-címkét a nyomkövetési vonalkóddal és a beszedendő összeggel. A nyomtatáshoz engedélyezze a felugró ablakokat ezen a webhelyen. A DHL, a FedEx és a UPS csak egyszer, a foglaláskor adja ki a címkéjét, és a Stocky megőrzi azt az újranyomtatáshoz.',
'Cr_Guide_T_Faq' => 'Hibaelhárítás',
'Cr_Guide_Q_Test' => 'A kapcsolat tesztelése sikertelen',
'Cr_Guide_A_Test' => 'A tesztkulcsok Teszt módhoz, az éles kulcsok Éles módhoz tartoznak; ezek eltérnek. Nyissa meg a Futárnaplókat, és a pontos okért olvassa el a futár válaszát.',
'Cr_Guide_Q_City' => 'A futár elutasítja a várost vagy a címet',
'Cr_Guide_A_City' => 'A foglalási űrlapon válassza ki a várost a futár városlistájából; a futárok csak a saját elnevezéseiket fogadják el. A postai címekkel dolgozó futároknak a megye, az irányítószám és a kétbetűs országkód is szükséges.',
'Cr_Guide_Q_Webhook' => 'Az állapotok nem változnak maguktól',
'Cr_Guide_A_Webhook' => 'A frissítéseket küldő futároknál ellenőrizze, hogy a webhook URL regisztrálva van-e a futárnál: a Futárnaplók minden fogadott frissítést megmutatnak, illetve azt is, miért utasítottak el egyet (például hibás titkos kulcs miatt). A többi futárt a Futárbeállításokban megadott ütemezés szerint ellenőrizzük, az Állapot ellenőrzése most pedig azonnal lekérdezi.',
'Cr_Guide_Q_Stuck' => 'Egy küldeménynél állapotellenőrzési hiba látható',
'Cr_Guide_A_Stuck' => 'A futár elutasította az utolsó ellenőrzéseket; az ok a küldeménynél és a Futárnaplókban látható. Ismételt hibák után a küldeményt a rendszer már nem ellenőrzi automatikusan: hárítsa el az okot, majd használja az Állapot ellenőrzése most funkciót.',
'Cr_Guide_Q_Label' => 'Címkenyomtatáskor semmi sem nyílik meg',
'Cr_Guide_A_Label' => 'A böngésző letiltotta a felugró ablakot. Engedélyezze a felugró ablakokat ezen a webhelyen, és próbálja újra.',
'Cr_Guide_Q_Cod' => 'Egy utánvétes kifizetés nem rögzült az eladáson',
'Cr_Guide_A_Cod' => 'A Futárbeállításokban az utánvéthez be kell kapcsolni a kapcsolót, és ki kell választani egy számlát. Számla nélkül a kifizetések csak kifizetettként lesznek megjelölve.',
