'Tfa_Reset' => 'Kétlépcsős hitelesítés visszaállítása',
'Tfa_Reset_Title' => 'Visszaállítja a kétlépcsős hitelesítést?',
'Tfa_Reset_Help' => 'A(z) :name felhasználó csak a jelszavával jelentkezik be, majd újra beállíthatja a hitelesítő alkalmazását. Csak akkor tegye ezt, ha meggyőződött arról, ki kéri.',
'Tfa_Guide_Lead' => 'A kétlépcsős hitelesítés (2FA) egy második lépést ad a bejelentkezéshez: a jelszó után a munkatársak egy 6 jegyű kódot írnak be a telefonjukon lévő hitelesítő alkalmazásból. Egy ellopott vagy kitalált jelszó már nem elég a belépéshez.',
