'Tfa_Guide_Staff_Title' => 'Minden munkatársnak',
'Tfa_Guide_App_Title' => 'Hitelesítő alkalmazás telepítése',
'Tfa_Guide_App_Text' => 'Bármely alkalmazás megfelel, amely támogatja a szabványos 6 jegyű kódokat (TOTP). Ingyenesek és offline is működnek:',
'Tfa_Guide_Enable_Title' => 'Bekapcsolás a profilban',
'Tfa_Guide_Enable_1' => 'Nyissa meg a Profilt (avatar menü jobb felül), és keresse meg a "Kétlépcsős hitelesítés" kártyát.',
'Tfa_Guide_Enable_2' => 'Kattintson a "Bekapcsolás" gombra, és erősítse meg a jelenlegi jelszóval.',
'Tfa_Guide_Enable_3' => 'Olvassa be a QR-kódot az alkalmazással, vagy írja be az alatta látható kulcsot.',
'Tfa_Guide_Enable_4' => 'A befejezéshez adja meg az alkalmazásban látható 6 jegyű kódot.',
'Tfa_Guide_Open_Profile' => 'Profilom megnyitása',
'Tfa_Guide_Codes_Title' => 'A helyreállítási kódok mentése',
'Tfa_Guide_Codes_Text' => 'Közvetlenül a beállítás után 8 helyreállítási kód jelenik meg egyetlen alkalommal. Mindegyik egyszer helyettesít egy telefonos kódot — elveszett, elromlott vagy visszaállított telefon esetén. Töltse le vagy másolja ki őket, és tárolja biztonságos helyen, a telefontól elkülönítve.',
'Tfa_Guide_Codes_Note' => 'Fogyóban vannak? A profilban az "Új helyreállítási kódok" a teljes készletet lecseréli; a régiek érvényüket vesztik.',
'Tfa_Guide_Signin_Title' => 'Bejelentkezés',
'Tfa_Guide_Signin_Text' => 'Az e-mail-cím és a jelszó után a bejelentkezési oldal az alkalmazásban látható aktuális kódot kéri. A kódok 30 másodpercenként változnak, és mindegyik csak egyszer használható.',
'Tfa_Guide_Signin_Trust' => 'A "Ne kérdezze újra ezen az eszközön" bejelölésével az adott böngészőben :days napig nem kell kódot megadni.',
'Tfa_Guide_Signin_Recovery' => 'Nincs kéznél a telefon? Kattintson a "Helyreállítási kód használata" lehetőségre, és írja be az egyik elmentett kódot.',
'Tfa_Guide_Admin_Title' => 'Rendszergazdáknak',
'Tfa_Guide_Require_Title' => 'Kötelezővé tétel',
'Tfa_Guide_Require_Text' => 'Kapcsolja be ezen a kártyán a "Kétlépcsős hitelesítés megkövetelése" opciót, majd válassza ki a szerepköröket, amelyeknek használniuk kell — vagy hagyja üresen a listát, ha minden felhasználónak kötelező. A mentéshez kattintson a Küldés gombra.',
'Tfa_Guide_Require_Next' => 'Senki sem lesz kijelentkeztetve. Azokat a felhasználókat, akiknek még nincs 2FA-juk, a következő bejelentkezéskor, a belépés előtt a bejelentkezési oldalon végigvezetjük a beállításon, és ott látják a helyreállítási kódjaikat is.',
'Tfa_Guide_Require_Note' => 'Akiknek kötelező, azok nem kapcsolhatják ki a profiljukban.',
'Tfa_Guide_Trust_Title' => 'Megbízható eszközök',
'Tfa_Guide_Trust_Text' => 'A "Megbízható eszközök megjegyzése" határozza meg, mennyi ideig hagyhatja ki egy böngésző a kódot egy sikeres bejelentkezés után. Közös vagy nyilvános számítógépekhez, például egy üzlettéri POS-hoz válassza a "Mindig kérjen kódot" lehetőséget.',
'Tfa_Guide_Trust_Note' => 'A szám csökkentése a már megbízhatónak jelölt eszközök idejét is lerövidíti; a 2FA kikapcsolása vagy visszaállítása mindet elfelejti.',
'Tfa_Guide_Lost_Title' => 'Elveszett telefon és nincsenek helyreállítási kódok',
'Tfa_Guide_Lost_Text' => 'A Felhasználók oldalon a 2FA-t használó felhasználóknál a 2FA oszlopban "Be" látható. A Műveletek alatti pajzs gomb visszaállítja: a felhasználó csak a jelszavával jelentkezik be, és újra beállítja az alkalmazást (vagy erre kérjük, ha kötelező).',
'Tfa_Guide_Lost_Warn' => 'Visszaállítás előtt győződjön meg arról, ki kéri — a visszaállítás megszünteti a 2FA által a fióknak nyújtott védelmet.',
'Tfa_Guide_Open_Users' => 'Felhasználók megnyitása',
'Tfa_Guide_Mobile_Title' => 'Mobilalkalmazás és API',
'Tfa_Guide_Mobile_Text' => 'A mobilalkalmazás és az API token végpontja ugyanezt a kódot kéri. Ha egy felhasználónak kötelező a 2FA, de még nem állította be, ehhez egyszer a weben kell bejelentkeznie.',
'Tfa_Guide_Protect_Title' => 'Beépített védelem',
'Tfa_Guide_Protect_1' => '5 hibás kód után az adott felhasználó 15 percig nem adhat meg kódot, a fenti zárolási beállításoktól függetlenül.',
'Tfa_Guide_Protect_2' => 'Minden kód és minden helyreállítási kód csak egyszer használható.',
'Tfa_Guide_Protect_3' => 'Ha a "Bejelentkezési tevékenység rögzítése" be van kapcsolva, a hibás kódok "Hibás 2FA-kód" bejegyzésként jelennek meg a Bejelentkezési tevékenység listában.',
'Tfa_Guide_Trouble_Title' => 'Hibaelhárítás',
'Tfa_Guide_Faq_Clock_Q' => '„A kód érvénytelen” friss kód esetén is',
'Tfa_Guide_Faq_Clock_A' => 'Valószínűleg pontatlan a telefon órája. A kódok az időtől függenek: állítsa a telefon dátumát és idejét automatikusra (hálózati idő), majd próbálja a következő kóddal.',
'Tfa_Guide_Faq_Phone_Q' => 'Áttérés új telefonra',
'Tfa_Guide_Faq_Phone_A' => 'Használja a hitelesítő alkalmazás saját átviteli funkcióját, vagy kapcsolja ki a 2FA-t a profilban, majd kapcsolja be újra az új telefonnal (ha kötelező, kérje meg inkább egy rendszergazdát a visszaállításra).',
'Tfa_Guide_Faq_Locked_Q' => '„Túl sok érvénytelen kód”',
'Tfa_Guide_Faq_Locked_A' => 'Várjon a megjelenített ideig (legfeljebb 15 percig), vagy kérje meg egy rendszergazdát, hogy állítsa vissza a felhasználó 2FA-ját.',
'Tfa_Guide_Faq_Key_Q' => 'Szerverköltöztetés után egyetlen 2FA-t használó felhasználó sem tud bejelentkezni',
'Tfa_Guide_Faq_Key_A' => 'A 2FA-titkok a .env fájlban lévő APP_KEY kulccsal vannak titkosítva. Az alkalmazás áthelyezésekor vagy visszaállításakor tartsa meg ugyanazt az APP_KEY-t; ha megváltozott, egy 2FA nélküli rendszergazdának kell visszaállítania az érintett felhasználókat.',
'Tfa_Guide_Button' => 'Útmutató',
'Tfa_Guide_Title' => 'Útmutató a kétlépcsős hitelesítéshez',
'Sec_2fa_Pending' => 'még :count felhasználónak kell beállítania',
'Sec_2fa_See_Who' => 'Kik ezek?',
'Sec_2fa_Grace_Off' => 'Nincs — beállítás a következő bejelentkezéskor',
'Sec_2fa_Applied' => ':count felhasználó kijelentkeztetve.',
'Tfa_Guide_Rollout_Title' => 'Bevezetés minden felhasználónál',
'Tfa_Guide_Rollout_1' => 'Először kapcsolja be a saját fiókjánál (Profil), hogy megismerje a lépéseket.',
'Tfa_Guide_Rollout_2' => 'Közölje a csapatával, melyik alkalmazást telepítsék, és hogy a beállítás egy percet vesz igénybe bejelentkezéskor.',
'Tfa_Guide_Rollout_3' => 'Kapcsolja be a "Kétlépcsős hitelesítés megkövetelése" opciót, hagyja üresen a "Kötelező ezeknek" mezőt (= minden felhasználó), és igény szerint válasszon türelmi időt. Kattintson a Küldés gombra.',
'Tfa_Guide_Rollout_4' => 'Kattintson a "2FA nélküli felhasználók kijelentkeztetése" gombra, hogy a már bejelentkezettek most állítsák be, ne egy későbbi bejelentkezéskor. Ön bejelentkezve marad.',
'Tfa_Guide_Rollout_5' => 'Kövesse nyomon a haladást a kártyán lévő számlálóval vagy a Felhasználók oldal "Beállítás szükséges" szűrőjével.',
'Tfa_Guide_Rollout_Note' => 'Türelmi idő esetén a beállítási képernyőn a határidőig megjelenik az „Emlékeztessen később” lehetőség; azt követően a bejelentkezéshez kötelező a beállítás.',
'Tfa_Guide_Customers_Title' => 'Vásárlói fiókok (áruház és ügyfélportál)',
'Tfa_Guide_Customers_Text' => 'A vásárlók is védhetik saját fiókjukat. Ez minden vásárló számára opcionális, és soha nem kötelező: kapcsolja be az Áruház beállításai → Regisztrációs hozzáférés-szabályozás (online áruház) és az Ügyfélportál → Portál beállításai (ügyfélportál) alatt.',
'Tfa_Guide_Customers_1' => 'A vásárlók a Fiókom (áruház) vagy a Profil (portál) oldalon kapcsolhatják be.',
'Tfa_Guide_Customers_2' => 'Választhatnak e-mailben küldött kódot — ez a legegyszerűbb, nem kell hozzá alkalmazás — vagy hitelesítő alkalmazást helyreállítási kódokkal.',
'Tfa_Guide_Customers_3' => 'Az e-mailben küldött kódokhoz működő levelezési beállítások szükségesek (Beállítások → Levelezési beállítások). A kódok 10 perc után lejárnak.',
'Tfa_Guide_Customers_4' => 'Ha később kikapcsolja az opciót, új beállítás nem lehetséges; a már használó vásárlóktól továbbra is kérjük a kódot, és ők maguk kapcsolhatják ki.',
'Tfa_Required_Grace_Notice' => 'A rendszergazda kétlépcsős hitelesítést ír elő. Bejelentkezéskor eddig halaszthatja el: :date; ezt követően a beállítás kötelező.',
