'Sec_2fa_Grace' => 'Türelmi idő',
'Sec_2fa_Grace_Help' => 'A határidőig a felhasználók a beállítási képernyőn választhatják az „Emlékeztessen később” lehetőséget, így senkit sem állítunk meg műszak közben. A követelmény bekapcsolásától számítva.',
